// 準備一個陣列來存放「有資料」的項目
const validItems = [];
let allEmpty = true; // 預設假設全部都是空的

for (const item of items) {
  let aiOutput = item.json.output;
  let chartJson = {};

  // 1. 嘗試解析 AI 輸出的 JSON
  try {
    // 清理可能存在的 Markdown 標記 (```json ... ```)
    if (typeof aiOutput === 'string') {
        const cleanString = aiOutput.replace(/```json/g, '').replace(/```/g, '').trim();
        chartJson = JSON.parse(cleanString);
    } else {
        chartJson = aiOutput;
    }
  } catch (error) {
    // 解析失敗，視為無資料，跳過
    continue;
  }

  // 2. 檢查標題是否包含「查無資料」
  const titleText = chartJson?.chart?.options?.title?.text;
  const titleString = Array.isArray(titleText) ? titleText.join('') : (titleText || '');

  // 3. 邏輯判斷
  if (titleString.includes('查無資料')) {
    // 這一筆是沒資料的，我們不做任何事 (不加入 validItems)
    // 但我們知道至少有一筆是無效的，不過 allEmpty 狀態取決於是否找到有效的
  } else {
    // 這一筆是有資料的！
    allEmpty = false; // 只要有一筆有資料，就不是「全空」

    // 把整理好的乾淨 JSON 放進去，方便後面使用
    item.json.finalChartConfig = chartJson;
    item.json.hasData = true; // 標記為 True
    validItems.push(item); // 加入有效清單
  }
}

// 4. 最終輸出決定
if (allEmpty) {
  // 情況 A：兩筆都沒資料 (validItems 是空的)
  // 回傳一個標記為 false 的項目，讓後面的 IF 走 False 路徑
  return [{
    json: {
      hasData: false,
      message: '所有查詢區間皆無資料'
    }
  }];
} else {
  // 情況 B：至少有一筆有資料 (或者是兩筆都有)
  // 只回傳「有資料」的那幾筆，濾掉沒資料的廢文
  // 這樣後面的節點就不會發出空白圖表
  return validItems;
}

// 取得輸入資料的 binary 數據
const binaryKey = Object.keys(items[0].binary)[0];

// *** 關鍵修改：強制將副檔名設為 PNG ***
const extension = 'png'; 

// 自訂 UUID 產生器（保持不變）
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

// 產生新檔名
const newFileName = `${generateUUID()}.${extension}`; // 例如: c8d0959f-d31e-450f-90e9-b223c6f37648.png

// 輸出結果
return [
  {
    binary: items[0].binary,
    json: {
      fileName: newFileName, // 輸出新的檔名給 Supabase 節點使用
    },
  },
];

